\section*{End Matter}
Here, we prove several basic results that are used in the main text. 

\noindent\textbf{Proof of Lemma.~\ref{tensor_ancilla_symplectic}} ---
Let $R := \mathbb{F}_2[x_1^{\pm 1}, \dots, x_D^{\pm 1}]$.

\begin{proposition}[Comparison theorem, {\cite[Theorem 2.2.6]{Weibel_1994}}]
\label{comparison_theorem}
    Given a projective resolution $P_\bullet \to_\epsilon M$ of an $R$-module $M$ and a resolution $Q_\bullet \to_\eta N$ of a $R$-module $N$, then for a map $f': M \to N$ there exists a chain map $f: P_\bullet \to Q_\bullet$, unique up to chain-homotopy, such that $\eta f_0 = f' \epsilon$.
\end{proposition}

\begin{corollary}
    \label{homotopy_equiv}
    Two projective resolutions $P_\bullet \to_\epsilon M$ and $Q_\bullet \to_\eta M$ of an $R$-module $M$ are chain-homotopy equivalent.
\end{corollary}
\begin{proof}
    From Proposition.~\ref{comparison_theorem} setting $f' = \mathrm{id}_M$ we have chain maps $f: P_\bullet \to Q_\bullet$ and $g: Q_\bullet \to P_\bullet$ such that $\eta f_0 = \epsilon$ and $\epsilon g_0 = \eta$. Composing them, we have $gf: P_\bullet \to P_\bullet$ is a chain map with $\epsilon (g_0 f_0) = \epsilon = \mathrm{id}_M \epsilon$. $id_{P_\bullet}$ is another chain map satisfying the same conditions. Applying Proposition.~\ref{comparison_theorem}, we get that $gf \simeq \mathrm{id}_{P_\bullet}$. Analogously, it can be shown that $fg \simeq \mathrm{id}_{Q_\bullet}$.
\end{proof}

\begin{proposition}[{\cite[Example 2.2.6]{KLEIN2016497}}]
    \label{property_complex}
    Let $\mathcal{A}$ be an exact category. Consider $\mathbf{C}^\mathrm{b}(\mathcal{A})$, the exact category of bounded complexes in $\mathcal{A}$ where the conflations are defined to be the short exact sequences which split degree-wise. $\mathbf{C}^\mathrm{b}(\mathcal{A})$ is a Frobenius category whose stable category $\underline{\mathbf{C}^\mathrm{b}(\mathcal{A})}$ is the bounded homotopy category of $\mathcal{A}$ and whose projective-injective objects are the bounded contractible complexes.
\end{proposition}

\begin{proposition}[{\cite[Lemma 2.1.27]{Krause_2021}}]
    \label{homotopy_to_iso}
    Let $\mathcal{A}$ be a Frobenius category and $\underline{\mathcal{A}}$ be its stable category. For objects $X$ and $Y$, $X \cong Y$ in $\underline{\mathcal{A}}$ if and only if $X \oplus I \cong Y \oplus J$ for injective objects $I, J \in \mathcal{A}$.
\end{proposition}

\begin{lemma}\label{almost_result}
    Given two bounded resolutions $P_\bullet \to M$ and $Q_\bullet \to M$ of a finitely-generated $R$-module $M$ by finitely-generated projective modules, there exist bounded contractible complexes of projective modules $C_\bullet$ and $C_\bullet'$ such that $P_\bullet + C_\bullet \cong Q_\bullet + C_\bullet'$.
\end{lemma}
\begin{proof}
    Consider the Frobenius category of bounded complexes of finitely generated projective $R$-modules $\mathbf{C}^\mathrm{b}(\mathrm{proj}\, R)$, per Proposition.~\ref{property_complex}. Thus its stable category coincides with its bounded homotopy category. As $P_\bullet \simeq Q_\bullet$ from Corollary.~\ref{homotopy_equiv}, we get from Propositions.~\ref{property_complex} and \ref{homotopy_to_iso} the desired result.
\end{proof}

\begin{proposition}\label{contractible_decomp}
    A bounded contractible complex $C_\bullet$ of projective $R$-modules is isomorphic to a direct sum of finitely many disks of the form $0 \to P \xrightarrow[]{\mathrm{id}} P \to 0$ where $P$ is projective.
\end{proposition}

\begin{proof}
From contractibility, we have the existence of a collection of maps $\{c_n\}$ such that $cd + dc = \mathrm{id}_{C_\bullet}$. At $C_{n}$, we can restrict to $Z_{n}$ so this becomes $d_{n+1} c_{n} \vert_{Z_{n}} = \mathrm{id}_{Z_{n}}$. Thus $B_{n} = \mathrm{im}\, d_{n+1} \supseteq Z_{n}$ and thus $C_\bullet$ is exact. Consider then the short exact sequence:
    \begin{align}
        0 \to Z_n \xrightarrow{\iota} C_n \xrightarrow{d_n} Z_{n-1} \to 0
    \end{align}
    As $d_n c_{n-1} \vert_{Z_{n-1}} = \mathrm{id}_{Z_{n-1}}$, the sequence splits with $C_n \cong Z_n \oplus Z_{n-1}$, and by the splitting lemma, there exists an isomorphism $h_n: C_n \to Z_n \oplus Z_{n-1}$ such that $h_n \iota = \left[\begin{smallmatrix}
        \mathrm{id}_{Z_n} \\ 0
    \end{smallmatrix}\right]$ and $d_n (h_n)^{-1} = \left[\begin{smallmatrix}
        0 & \mathrm{id}_{Z_{n-1}}
    \end{smallmatrix}\right]$. It can be checked that $h_n$ gives a chain map between $C_\bullet$ and the chain complex $D_\bullet$ with $D_n = Z_{n} \oplus Z_{n-1}$ and differential $\left[\begin{smallmatrix}
        0 & \mathrm{id}_{Z_{n-1}} \\ 0 & 0
    \end{smallmatrix}\right]$. As each $Z_n$ is a summand of $C_n$ and thus projective, the claim follows with disks of the form $0 \to Z_n \to Z_n \to 0$ (and as finitely many $Z_n$ are nonzero, there are finitely many non-zero disks).

\end{proof}

\begin{proof}[Proof of Lemma.~\ref{tensor_ancilla_symplectic}]
    This follows immediately from Lemma.~\ref{almost_result} and Proposition.~\ref{contractible_decomp}, along with the well-known fact that all finitely-generated projective modules over the Laurent polynomial ring are free \cite{19305ce2-3cfa-35d1-a4a5-425a28d871f5,1976InMat..36..167Q}.
\end{proof}

\clearpage

\noindent\textbf{Proof of Proposition.~\ref{d-dim-complex}} ---
Let $R := \mathbb{F}_2[x_1^{\pm 1}, \dots, x_D^{\pm 1}]$.

\begin{proof}[Proof of Proposition.~\ref{d-dim-complex}]
We first note that the cochain complex (with respect to the $R$-module structure) $\mathrm{Hom}_R(F_\bullet,R)$ is isomorphic to the ZX-dual complex $F^\bullet$ under $f \mapsto \sum_i \overline{f(e_i)} e_i$. We can thus reformulate the conditions of the proposition as $\mathrm{grade}_R(M) \geq D$, where $\mathrm{grade}_R(M)$ measures how long the cochain complex remains exact. By a famous result of Rees'~\cite{Rees_1957}, $\mathrm{grade}_R (R/J) = \mathrm{grade}_R(M)$, where $J = \mathrm{ann}_R (M)$. The former is typically written as $\mathrm{grade}_R (J)$. We have $\mathrm{grade}_R(J) \leq \mathrm{codim}(J)$~\cite{Matsumura_1987} and thus $\mathrm{codim}(J) = D$. It follows that $M$ is a zero-dimensional module.
\end{proof}

