    \centering

    \caption{The relation between the failure rate and the principal angle between the weak eigenspaces of the estimator and of the true state at a fixed trace distance of $0.05$ and $d=4$. The condition of failure is identical to Fig.~\ref{fig:capture_rate}. The same 200 true states and POVMs are used at every data point, with the starting states perturbed to the same trace distance but at different angles. $\phi=0$ corresponds to a rotation acting only within the strong and weak blocks separately.}
    \label{fig:angle}
\end{figure}

