\section{M\"obius expansion and proof of Theorem~\ref{thm:mobius}}
\label{app:mobius-proof}

For \(\mathbf i=(i_1,\ldots,i_M)\in[N]^M\), define
\begin{equation}
X(\mathbf i):=\left(\prod_{t=1}^Mp_{i_t}\right)\bigotimes_{t=1}^M\rho_{i_t}^{(t)}.
\label{eq:sequence-state}
\end{equation}
For \(S,R\in\Part([M])\), define the exact equality-pattern sum and the diagonal sum, respectively, by
\begin{equation}
G_S:=\sum_{\mathbf i:\eqp(\mathbf i)=S}X(\mathbf i),\qquad H_R:=\sum_{\mathbf i:\eqp(\mathbf i)\succeq R}X(\mathbf i).
\label{eq:exact-and-diagonal-sums}
\end{equation}
In particular, \(\Omega_\Pi=G_\Pi\). We use \(S\succeq R\) to mean that \(S\) is coarser than or equal to \(R\), and \(S\succ R\) for strict coarsening. For example, if \(M=3\), \(R=\{\{1\},\{2\},\{3\}\}=\hat 0\), and \(S=\{\{1,2\},\{3\}\}\), then \(S\succ R\) because every block of \(R\) is contained in a block of \(S\). Since every sequence \(\mathbf i\) has a unique equality partition,
\begin{equation}
H_R=\sum_{S\succeq R}G_S.
\label{eq:zeta-transform}
\end{equation}
Equation~\eqref{eq:zeta-transform} is the zeta transform on the finite poset \(\Part([M])\). M\"obius inversion \cite{Rota1964OnTFmobius} therefore gives
\begin{equation}
G_\Pi=\sum_{R\succeq\Pi}\mu(\Pi,R)H_R.
\label{eq:mobius-inversion-G}
\end{equation}

We next identify \(H_R\). Let \(R=\{D_1,\ldots,D_\ell\}\). The condition \(\eqp(\mathbf i)\succeq R\) requires all positions within each block \(D\in R\) to carry the same intrinsic component label, while labels assigned to different blocks are summed independently and need not be distinct. By contrast, if \(\eqp(\mathbf i)=R\), distinct blocks must carry distinct labels. Hence
\begin{align}
H_R&=\sum_{(j_D)_{D\in R}\in[N]^{|R|}}\left(\prod_{D\in R}p_{j_D}^{|D|}\right)\bigotimes_{D\in R}\bigotimes_{t\in D}\rho_{j_D}^{(t)}\notag\\
&=\bigotimes_{D\in R}\left(\sum_{j=1}^Np_j^{|D|}\bigotimes_{t\in D}\rho_j^{(t)}\right)=\bigotimes_{D\in R}\mathcal K^{(|D|)},
\label{eq:diagonal-sum-factorization}
\end{align}
where each moment operator acts on the registers indexed by \(D\). Substituting Eq.~\eqref{eq:diagonal-sum-factorization} into Eq.~\eqref{eq:mobius-inversion-G} and using \(\Omega_\Pi=G_\Pi\) yields
\[
\Omega_\Pi=\sum_{R\succeq\Pi}\mu(\Pi,R)\bigotimes_{D\in R}\mathcal K^{(|D|)},
\]
which is Eq.~\eqref{eq:Mobius-general}.

It remains to determine the M\"obius coefficient explicitly. For \(R\succeq\Pi\) and \(D\in R\), define
\begin{equation}
m_D:=\#\{B\in\Pi:B\subseteq D\},
\label{eq:number-merged-blocks}
\end{equation}
the number of blocks of \(\Pi\) merged into \(D\). The interval \([\Pi,R]\) decomposes into independent partition lattices associated with the blocks of \(R\): for each \(D\in R\), the corresponding factor is the partition lattice of the \(m_D\) blocks of \(\Pi\) contained in \(D\). Thus
\begin{equation}
[\Pi,R]\cong\prod_{D\in R}\Pi_{m_D},
\label{eq:partition-interval-product}
\end{equation}
where \(\Pi_{m_D}\) denotes the partition lattice of a set with \(m_D\) elements. Using multiplicativity of the M\"obius function under direct products and the standard identity \(\mu_{\Pi_m}(\hat 0,\hat 1)=(-1)^{m-1}(m-1)!\) \cite{Rota1964OnTFmobius}, we obtain
\begin{equation}
\mu(\Pi,R)=\prod_{D\in R}(-1)^{m_D-1}(m_D-1)!.
\label{eq:explicit-mobius-coefficient}
\end{equation}
This proves Eq.~\eqref{eq:Mobius-general}.

For a uniform ensemble, \(p_i=1/N\), the power-weighted and ordinary moment operators satisfy
\begin{equation}
\mathcal K^{(|D|)}=N^{1-|D|}\calM^{(|D|)},\qquad \calM^{(|D|)}:=\frac1N\sum_{i=1}^N\bigotimes_{t\in D}\rho_i^{(t)}.
\label{eq:uniform-power-ordinary-relation}
\end{equation}
Therefore,
\begin{equation}
\bigotimes_{D\in R}\mathcal K^{(|D|)}=N^{\sum_{D\in R}(1-|D|)}\bigotimes_{D\in R}\calM^{(|D|)}=N^{|R|-M}\bigotimes_{D\in R}\calM^{(|D|)},
\label{eq:uniform-moment-product}
\end{equation}
where \(\sum_{D\in R}|D|=M\). Substituting Eq.~\eqref{eq:uniform-moment-product} into Eq.~\eqref{eq:Mobius-general} gives
\[
\Omega_\Pi=\sum_{R\succeq\Pi}\mu(\Pi,R)N^{|R|-M}\bigotimes_{D\in R}\calM^{(|D|)},
\]
which is Eq.~\eqref{eq:Mobius-uniform} and completes the proof of Theorem~\ref{thm:mobius}.

\section{Proof of Theorem~\ref{thm:opt} and the classical limit}
\label{sec:proof_theorem1}

\begin{proof}[Proof of Theorem~\ref{thm:opt}]
For each hypothesis \(h\in\{0,1\}\) and equality pattern \(\Pi\in\Part([M])\), recall the unnormalized branch state
\[
\Omega_{h,\Pi}:=\sum_{\substack{\mathbf i\in[N]^M:\\\operatorname{eq}(\mathbf i)=\Pi}}\left(\prod_{t=1}^Mp_{i_t}^{(h)}\right)\bigotimes_{t=1}^M\rho_{i_t}^{(h)},
\]
whose trace \(\Tr\Omega_{h,\Pi}\) is the probability of observing \(\Pi\) under \(H_h\). For a branch-dependent binary POVM \(\{E_{0|\Pi},E_{1|\Pi}\}\), define the Helstrom operator
\begin{equation}
D_\Pi:=\eta_0\Omega_{0,\Pi}-\eta_1\Omega_{1,\Pi}.
\label{eq:branch-Helstrom-operator}
\end{equation}
Using \(E_{1|\Pi}=I-E_{0|\Pi}\), the contribution of branch \(\Pi\) to the unconditional Bayes error is
\begin{equation}
R_\Pi(E_{0|\Pi}):=\eta_0\Tr(E_{1|\Pi}\Omega_{0,\Pi})+\eta_1\Tr(E_{0|\Pi}\Omega_{1,\Pi})=\eta_0\Tr\Omega_{0,\Pi}-\Tr(E_{0|\Pi}D_\Pi).
\label{eq:branch-Bayes-risk}
\end{equation}
Thus, minimizing the branch error is equivalent to maximizing \(\Tr(E_{0|\Pi}D_\Pi)\) over all effects \(0\le E_{0|\Pi}\le I\).

Let \(D_\Pi=\sum_j\lambda_j\ket{j}\!\bra{j}\) be a spectral decomposition. For any effect \(0\le E\le I\),
\[
\Tr(ED_\Pi)=\sum_j\lambda_j\langle j|E|j\rangle\le\sum_{\lambda_j>0}\lambda_j=\Tr D_{\Pi,+},
\]
where \(D_{\Pi,+}\) is the positive part of \(D_\Pi\). Equality is attained by \(E=\Pi_+(D_\Pi)\), the projector onto the positive eigenspace of \(D_\Pi\). Hence
\[
E_{0|\Pi}^{\mathrm{opt}}=\Pi_+(D_\Pi),\qquad E_{1|\Pi}^{\mathrm{opt}}=I-\Pi_+(D_\Pi).
\]
Using \(\Tr D_{\Pi,+}=\frac12(\Tr D_\Pi+\|D_\Pi\|_1)\), the optimal branch error is
\begin{equation}
R_\Pi^{\mathrm{opt}}=\frac12\left[\eta_0\Tr\Omega_{0,\Pi}+\eta_1\Tr\Omega_{1,\Pi}-\|D_\Pi\|_1\right].
\label{eq:optimal-branch-Bayes-risk}
\end{equation}
Finally, since \(\sum_{\Pi\in\Part([M])}\Tr\Omega_{h,\Pi}=1\) for \(h=0,1\), summing Eq.~\eqref{eq:optimal-branch-Bayes-risk} over all equality patterns gives
\[
P_{e,\mathrm{opt}}^{(M)}=\sum_{\Pi\in\Part([M])}R_\Pi^{\mathrm{opt}}=\frac12\left[1-\sum_{\Pi\in\Part([M])}\|\eta_0\Omega_{0,\Pi}-\eta_1\Omega_{1,\Pi}\|_1\right],
\]
which proves Eq.~\eqref{eq:Bayes-exact}.
\end{proof}

We formally write down the classical limit as a corollary, then provide the prove.
\begin{corollary}[Classical limit]
    In classical limit, the exact Bayes error is
    \begin{equation}
    P_{e,{\rm opt},c}^{(M)} = \frac12\left[1-\|\eta_0[{\bm p}^{(0)}]^{\otimes M}-\eta_1[{\bm p}^{(1)}]^{\otimes M}\|_1\right] ,
    \label{eq:Bayes-exact-classical-supp}
    \end{equation}
    which recovers the well-knwon classical formula, where ${\bm p}^{\otimes M}$ is the tensor product of probability.\label{cor:classical limit Bayes error}
\end{corollary}
\begin{proof}[Proof of Corollary~\ref{cor:classical limit Bayes error}]
In the classical limit, the component states under both hypotheses are the same mutually orthogonal states, \(\rho_i^{(0)}=\rho_i^{(1)}=\ket{i}\!\bra{i}\), where \(\{\ket{i}\}_{i=1}^N\) is an orthonormal basis. Define \(\mathbf p^{(h)}:=(p_1^{(h)},\ldots,p_N^{(h)})\), \(\ket{\mathbf i}:=\bigotimes_{t=1}^M\ket{i_t}\), and \([\mathbf p^{(h)}]_{\mathbf i}^{\otimes M}:=\prod_{t=1}^Mp_{i_t}^{(h)}\). The branch states are diagonal in the common product basis:
\begin{equation}
\Omega_{h,\Pi}=\sum_{\substack{\mathbf i\in[N]^M:\\\operatorname{eq}(\mathbf i)=\Pi}}[\mathbf p^{(h)}]_{\mathbf i}^{\otimes M}\ket{\mathbf i}\!\bra{\mathbf i}.
\label{eq:classical-branch-state}
\end{equation}
Consequently,
\begin{equation}
\|\eta_0\Omega_{0,\Pi}-\eta_1\Omega_{1,\Pi}\|_1=\sum_{\substack{\mathbf i\in[N]^M:\\\operatorname{eq}(\mathbf i)=\Pi}}\left|\eta_0[\mathbf p^{(0)}]_{\mathbf i}^{\otimes M}-\eta_1[\mathbf p^{(1)}]_{\mathbf i}^{\otimes M}\right|.
\label{eq:classical-branch-trace-norm}
\end{equation}
Since the sets \(\{\mathbf i\in[N]^M:\operatorname{eq}(\mathbf i)=\Pi\}\), \(\Pi\in\Part([M])\), form a partition of \([N]^M\), summing Eq.~\eqref{eq:classical-branch-trace-norm} over \(\Pi\) yields
\begin{equation}
\sum_{\Pi\in\Part([M])}\|\eta_0\Omega_{0,\Pi}-\eta_1\Omega_{1,\Pi}\|_1=\left\|\eta_0[\mathbf p^{(0)}]^{\otimes M}-\eta_1[\mathbf p^{(1)}]^{\otimes M}\right\|_1.
\label{eq:classical-total-variation-reduction}
\end{equation}
Substituting Eq.~\eqref{eq:classical-total-variation-reduction} into Eq.~\eqref{eq:Bayes-exact} gives
\[
P_{e,\mathrm{opt},c}^{(M)}=\frac12\left[1-\left\|\eta_0[\mathbf p^{(0)}]^{\otimes M}-\eta_1[\mathbf p^{(1)}]^{\otimes M}\right\|_1\right],
\]
which is the standard classical Bayes error.
\end{proof}

\section{Proof of Theorem~\ref{thm:fixed-N-chernoff-bounds-main}}
\label{app:proof_theorem2}
We recall the definitions needed and results here. In the many-sample regime, we consider the error exponent \(E:=\lim_{M\to\infty}-\log\left( P_{e,\mathrm{opt}}^{(M)}\right)/M\). Writing \(Q_s(A,B):=\Tr(A^sB^{1-s})\), define the fixed-permutation Chernoff information and the corresponding across-hypothesis and in-hypothesis permutation bottlenecks by
\begin{align}
\xi_\pi^{h,h'}&:=-\log\min_{0\le s\le1}\sum_{i=1}^N Q_s\!\left(p_i^{(h)}\rho_i^{(h)},p_{\pi(i)}^{(h')}\rho_{\pi(i)}^{(h')}\right),\notag\\
\xi_{\mathrm{acr}}&:=\min_{\pi\in S_N}\xi_\pi^{0,1},\qquad \xi_{\mathrm{in}}:=\min_{h\in\{0,1\}}\min_{\pi\in S_N\setminus\{\mathrm{id}\}}\xi_\pi^{h,h}.
\label{eq:generalized-permutation-chernoff}
\end{align}

\begin{theorem}[Asymptotic Chernoff bounds for optimal Bayes error]
\label{thm:fixed-N-chernoff-bounds}
The error exponent $E$ has the following lower and upper bounds
\begin{equation}
    \min\{\xi_{\mathrm{in}},\xi_{\mathrm{acr}}\}\le E\le \xi_{\mathrm{acr}}.
\end{equation}

For testing between finite uniform pure state ensembles, we have
$
        E = \xi_{\text{acr}}.
$

Moreover, for finite uniform pure-state ensembles of equal cardinality, with fidelity cost
$C_{ij}=1-\Tr(\rho_i^{(0)}\rho_j^{(1)})$, the across-hypothesis Chernoff exponent and the Wasserstein distance satisfy
\[
    \xi_{\mathrm{acr}}
    =-\log\!\left[1-W(\mathcal E_0,\mathcal E_1)\right],
\]
or equivalently,
$W(\mathcal E_0,\mathcal E_1)=1-e^{-\xi_{\mathrm{acr}}}$.
\end{theorem}
\begin{proof}
    The proof contains four parts, first, we prove the lower bound, second, we prove the upper bound, third, we prove that the upper bound is tight for uniform pure ensembles. Finally we show the relation between Chernoff exponent and Wasserstein distance for uniform pure-state ensembles.

\paragraph{\textbf{Lower bound.}} The lower bound on \(E\) is obtained by first discriminating the finer hypotheses \((h,\alpha)\), which specify both the ensemble hypothesis and its labeling, and then merging all outcomes corresponding to the same \(h\). For \(h\in\{0,1\}\) and \(\alpha\in S_N\), define
\begin{equation}
\widetilde\rho_{h,\alpha}:=\bigoplus_{i=1}^Np_{\alpha(i)}^{(h)}\rho_{\alpha(i)}^{(h)},\qquad \mathcal C^{(h)}:=\{\widetilde\rho_{h,\alpha}:\alpha\in S_N\},\qquad \mathcal W:=\mathcal C^{(0)}\cup\mathcal C^{(1)}.
\label{eq:permuted-direct-sum-states}
\end{equation}
To relate this refined description to the original label-invariant experiment, define the permutation-averaged states
\begin{equation}
\overline\rho_h^{(M)}:=\frac1{|S_N|}\sum_{\alpha\in S_N}\widetilde\rho_{h,\alpha}^{\otimes M}.
\label{eq:permutation-averaged-states}
\end{equation}

For a direct-sum label sequence $\boldsymbol{\lambda}\in[N]^M$ with equality pattern $\Pi$ and $s=|\Pi|$ distinct labels, each injective assignment of these labels to intrinsic component labels extends to $(N-s)!$ permutations. Hence, the block indexed by $\boldsymbol{\lambda}$ equals $\Omega_{h,\Pi}/(N)_s$. Since there are $(N)_s$ observed-label sequences with equality pattern $\Pi$, index these identical orthogonal blocks by $a\in[(N)_s]$. Hence, up to a reordering of orthogonal direct-sum blocks,
\begin{equation}
\overline\rho_h^{(M)}\cong\bigoplus_{\Pi\in\Part([M])}\bigoplus_{a=1}^{(N)_s}\frac{\Omega_{h,\Pi}}{(N)_s},\qquad (N)_s:=\frac{N!}{(N-s)!}.
\label{eq:permutation-average-branch-decomposition}
\end{equation}
The additivity of the trace norm over direct sums and Theorem~\ref{thm:opt} therefore give
\begin{equation}
P_{e,\mathrm{opt}}^{(M)}=\frac12\left[1-\left\|\eta_0\overline\rho_0^{(M)}-\eta_1\overline\rho_1^{(M)}\right\|_1\right].
\label{eq:twirled-Bayes-error}
\end{equation}

Apply the multiple quantum Chernoff theorem \cite{Li2016multiplequantumchernoff10.1214/16-AOS1436}\footnote{It is required that the states have a common finite-dimensional joint support, which is satisfied since we only consider ensembles with finite states.} to the states \(\{\widetilde\rho_{h,\alpha}^{\otimes M}\}_{h,\alpha}\) with priors \(\eta_h/|S_N|\). There exists a sequence of POVMs \(\{\Lambda_{h,\alpha}^{(M)}\}_{h,\alpha}\) whose average error satisfies
\begin{equation}
P_{e,\mathrm{mult}}^{(M)}(\Lambda)\le\exp[-M(\xi_{\mathrm{mult}}-o(1))],
\label{eq:multiple-Chernoff-achievability}
\end{equation}
where
\[
\xi_{\mathrm{mult}}:=\min_{\substack{(h,\alpha)\ne(h',\beta)}}\sup_{0\le s\le1}\left\{-\log\Tr\!\left[(\widetilde\rho_{h,\alpha})^s(\widetilde\rho_{h',\beta})^{1-s}\right]\right\}.
\]
The direct-sum structure gives
\[
\Tr\!\left[(\widetilde\rho_{h,\alpha})^s(\widetilde\rho_{h',\beta})^{1-s}\right]=\sum_{i=1}^N\left(p_{\alpha(i)}^{(h)}\right)^s\left(p_{\beta(i)}^{(h')}\right)^{1-s}\Tr\!\left[\left(\rho_{\alpha(i)}^{(h)}\right)^s\left(\rho_{\beta(i)}^{(h')}\right)^{1-s}\right]=C_{\beta\circ\alpha^{-1}}^{h,h'}(s).
\]
Pairs with \(h\ne h'\) yield the across-hypothesis bottleneck \(\xi_{\mathrm{acr}}\), whereas pairs with \(h=h'\) and \(\alpha\ne\beta\) yield the in-hypothesis bottleneck \(\xi_{\mathrm{in}}\). Therefore,
\begin{equation}
\xi_{\mathrm{mult}}=\min\{\xi_{\mathrm{in}},\xi_{\mathrm{acr}}\}.
\label{eq:multiple-Chernoff-bottleneck}
\end{equation}

Merge the fine-grained outcomes according to the ensemble hypothesis by defining
\[
F_h^{(M)}:=\sum_{\alpha\in S_N}\Lambda_{h,\alpha}^{(M)},\qquad h=0,1.
\]
Then \(\{F_0^{(M)},F_1^{(M)}\}\) is a binary POVM. For every \(h\) and \(\alpha\),
\[
F_{1-h}^{(M)}=\sum_{\beta\in S_N}\Lambda_{1-h,\beta}^{(M)}\preceq I-\Lambda_{h,\alpha}^{(M)},
\]
and hence
\[
\sum_{h=0}^1\eta_h\Tr\!\left[\overline\rho_h^{(M)}F_{1-h}^{(M)}\right]=\sum_{h=0}^1\frac{\eta_h}{|S_N|}\sum_{\alpha\in S_N}\Tr\!\left[\widetilde\rho_{h,\alpha}^{\otimes M}F_{1-h}^{(M)}\right]\le P_{e,\mathrm{mult}}^{(M)}(\Lambda).
\]
Using Eq.~\eqref{eq:twirled-Bayes-error} and Eq.~\eqref{eq:multiple-Chernoff-achievability}, we obtain
\[
P_{e,\mathrm{opt}}^{(M)}\le\exp[-M(\min\{\xi_{\mathrm{in}},\xi_{\mathrm{acr}}\}-o(1))],
\]
and therefore
\begin{equation}
E\ge\min\{\xi_{\mathrm{in}},\xi_{\mathrm{acr}}\}.
\label{eq:Chernoff-exponent-lower-bound}
\end{equation}

\paragraph{\textbf{Upper bound.}} Fix \(\pi\in S_N\), set \(\widetilde\rho_0:=\widetilde\rho_{0,\mathrm{id}}\), and let \(P_{e,\pi,\mathrm{ref}}^{(M)}\) be the optimal Bayes error for the refined i.i.d. test
\[
\widetilde\rho_0^{\otimes M}\quad\text{versus}\quad\widetilde\rho_{1,\pi}^{\otimes M}.
\]
Coarse-graining the direct-sum index sequence to its equality pattern recovers the original label-invariant experiment. The refined test therefore has no larger error:
\[
P_{e,\mathrm{opt}}^{(M)}\ge P_{e,\pi,\mathrm{ref}}^{(M)}.
\]
The quantum Chernoff theorem \cite{audenaert} gives
\[
\lim_{M\to\infty}-\frac1M\log P_{e,\pi,\mathrm{ref}}^{(M)}=\sup_{0\le s\le1}\bigl[-\log C_\pi^{0,1}(s)\bigr]=\xi_\pi^{0,1}.
\]
Consequently, \(E\le\xi_\pi^{0,1}\) for every \(\pi\in S_N\), and hence
\begin{equation}
E\le\min_{\pi\in S_N}\xi_\pi^{0,1}=\xi_{\mathrm{acr}}.
\label{eq:Chernoff-exponent-upper-bound}
\end{equation}

\paragraph{\textbf{Achievability of upper bound for uniform pure ensembles}}
To show the achievability, we construct a specific POVM for any pair of uniform pure ensembles and directly give the exact Bayes error $P^{(M)}_e\le c \exp{-M\xi_\text{acr}}$, hence the corresponding Chernoff exponent $E\ge\xi_\text{acr}$, since we already have $E\le\xi_\text{acr}$, we then get $E=\xi_\text{acr}$.

Assume $p_i^{(h)}=1/N$ and $\rho_i^{(h)}=\ketbra{\psi_i^{(h)}}$. For a possible branch $\Pi\in\Part([M])$, set $\mathcal A_\Pi:=\operatorname{Inj}(\Pi,[N])$, representing all possible injections indicating the intrinsic states of labels in the observed parition. For $\alpha\in\mathcal A_\Pi$, define $\ket{\Phi_{\Pi,\alpha}^{(h)}}:=\bigotimes_{B\in\Pi}\bigotimes_{m\in B}\ket{\psi_{\alpha(B)}^{(h)}}_m$, where the tensor factors are placed in the physical sample order. Then the state representing the partiion $\Pi$ can also be written as
\begin{equation}
\Omega_{h,\Pi}=N^{-M}\sum_{\alpha\in\mathcal A_\Pi}\ketbra{\Phi_{\Pi,\alpha}^{(h)}}.
\label{eq:pure-uniform-branch-expansion}
\end{equation}

We now give the specific POVM used for testing. For each branch $\Pi$, use the support test $E_{1|\Pi}:=P_{1,\Pi}$ and $E_{0|\Pi}:=I-P_{1,\Pi}$. These branchwise measurements form a valid block-diagonal POVM. Since $\Omega_{1,\Pi}$ is supported on $P_{1,\Pi}$, the error under $H_1$ vanishes, and hence the exact Bayes error is
\begin{equation}
P_e^{(M)}\le\eta_0\sum_{\Pi\in\Part([M])}\Tr(\Omega_{0,\Pi}P_{1,\Pi}).
\end{equation}

To show $P^{(M)}_e\le c \exp{-M\xi_\text{acr}}$, we first prove a lemma.

\begin{lemma}
    Define $T_{1,\Pi}:=\sum_{\alpha\in\mathcal A_\Pi}\ketbra{\Phi_{\Pi,\alpha}^{(1)}}$ and $P_{1,\Pi}:=\operatorname{proj}\!\left(\Span\{\ket{\Phi_{\Pi,\alpha}^{(1)}}:\alpha\in\mathcal A_\Pi\}\right)$. We claim that there exists a constant $\kappa>0$, depending only on $\mathcal E_1$, such that
\begin{equation}
T_{1,\Pi}\succeq\kappa P_{1,\Pi}
\label{eq:uniform-branch-frame-bound}
\end{equation}
for every $M$ and every possible branch $\Pi$.
\end{lemma}

\begin{proof}
    Let $V_\Pi:\mathbb C^{\mathcal A_\Pi}\to\mathcal H^{\otimes M}$ be the synthesis map defined by $V_\Pi e_\alpha=\ket{\Phi_{\Pi,\alpha}^{(1)}}$, where $\{e_\alpha\}_{\alpha\in\mathcal A_\Pi}$ is the standard basis of $\mathbb C^{\mathcal A_\Pi}$\footnote{Equivalently, $V_\Pi$ is the matrix whose columns are the branch vectors, and $\dim \mathbb C^{\mathcal A_\Pi}$ is the number of possible injections $\frac{N!}{(N-|\Pi|)!}$.}. Since $T_{1,\Pi}=V_\Pi V_\Pi^\dagger$ and $P_{1,\Pi}$ is the projector onto $\operatorname{ran}V_\Pi$, it suffices to prove that the nonzero singular values of all $V_\Pi$ are bounded below by a positive constant independent of $M$ and $\Pi$.

Suppose otherwise. Then there exist integers $M_\ell$, branches $\Pi_\ell\in\Part([M_\ell])$, and unit vectors $z_\ell\in(\ker V_{\Pi_\ell})^\perp$ such that $\norm{V_{\Pi_\ell}z_\ell}\to0$. Since $|\Pi_\ell|\le N$, after passing to a subsequence we may assume $|\Pi_\ell|=s$ for all $\ell$. Order the blocks as $\Pi_\ell=\{B_{1,\ell},\ldots,B_{s,\ell}\}$ and identify each $\mathcal A_{\Pi_\ell}$ with the fixed set $\mathcal A_s:=\operatorname{Inj}([s],[N])$. After permuting the output registers, which preserves norms, singular values, and kernels, write the resulting synthesis map as $V_\ell$. Its columns are $V_\ell e_\alpha=\bigotimes_{a=1}^s\ket{\psi_{\alpha(a)}^{(1)}}^{\otimes n_{a,\ell}}$, where $n_{a,\ell}:=|B_{a,\ell}|$. Since $\norm{V_\ell}\le\sqrt{|\mathcal A_s|}$, compactness of the unit sphere in $\mathbb C^{\mathcal A_s}$ gives a further subsequence such that $z_\ell\to z_\infty$ with $\norm{z_\infty}=1$. Writing $z_\infty=((z_\infty)_\alpha)_{\alpha\in\mathcal A_s}$ in the standard basis of $\mathbb C^{\mathcal A_s}$, we have
\begin{equation}
\norm{V_\ell z_\infty}\le\norm{V_\ell z_\ell}+\norm{V_\ell}\norm{z_\infty-z_\ell}\longrightarrow0.
\end{equation}

Passing to another subsequence, for each $a\in[s]$, either $n_{a,\ell}$ is eventually constant or $n_{a,\ell}\to\infty$. Let $\mathsf F$ and $\mathsf L$ denote the corresponding sets of indices, and for $a\in\mathsf F$ let $n_a$ be the eventual value of $n_{a,\ell}$. Define an equivalence relation on $[N]$ by $i\sim j$ if and only if $\rho_i^{(1)}=\rho_j^{(1)}$. Since the set of distinct states in an ensemble is finite, there exists $q<1$ such that $|\braket{\psi_i^{(1)}}{\psi_j^{(1)}}|\le q$ whenever $i\not\sim j$.

Group the elements of $\mathcal A_s$ into equivalence classes as follows: $\alpha$ and $\beta$ belong to the same equivalence class $C$ if and only if $\alpha(a)$ and $\beta(a)$ correspond to the same state (or $\alpha(a)\sim\beta(a)$) for every $a\in\mathsf L$. For each class $C$, choose $\alpha_C\in C$ and define $u_{C,\ell}:=\bigotimes_{a\in\mathsf L}\ket{\psi_{\alpha_C(a)}^{(1)}}^{\otimes n_{a,\ell}}$, $w_\alpha:=\bigotimes_{a\in\mathsf F}\ket{\psi_{\alpha(a)}^{(1)}}^{\otimes n_a}$, and $y_C:=\sum_{\alpha\in C}(z_\infty)_\alpha w_\alpha$. Then for all sufficiently large $\ell$ we have $V_\ell z_\infty=\sum_Cu_{C,\ell}\otimes y_C$.

If $C\ne C'$, then for some $a\in\mathsf L$ the labels $\alpha_C(a)$ and $\alpha_{C'}(a)$ correspond to distinct states. Since different classes become asymptotically orthogonal, expanding the squared norm gives
\[
\lim_{\ell\to\infty}\|V_\ell z_\infty\|^2=\sum_C\|y_C\|^2.
\]
The left-hand side is zero, and the right-hand side is a finite sum of nonnegative constants independent of $\ell$. Hence $y_C=0$ for every class $C$. For sufficiently large $\ell$, the decomposition $V_\ell z_\infty=\sum_Cu_{C,\ell}\otimes y_C$ holds exactly, and therefore $V_\ell z_\infty=0$, that is,  $z_\infty\in\ker V_\ell$. Since $z_\ell\in(\ker V_\ell)^\perp$, we have $\langle z_\ell,z_\infty\rangle=0$ for all sufficiently large $\ell$, contradicting $z_\ell\to z_\infty$ and $\norm{z_\infty}=1$. Thus there exists $\gamma>0$ such that every nonzero singular value of every $V_\Pi$ is at least $\gamma$. Consequently, $T_{1,\Pi}=V_\Pi V_\Pi^\dagger\succeq\gamma^2P_{1,\Pi}$, proving Eq.~\eqref{eq:uniform-branch-frame-bound} with $\kappa=\gamma^2$.
\end{proof}

Define
\begin{equation}
F_{ij}:=\Tr(\rho_i^{(0)}\rho_j^{(1)})=|\braket{\psi_i^{(0)}}{\psi_j^{(1)}}|^2,\qquad F_\star:=\max_{\pi\in S_N}\frac1N\sum_{i=1}^NF_{i,\pi(i)}.
\label{eq:F-star-definition}
\end{equation}
For a rank-one projector, with the standard support convention at exponent zero, $(\rho_i^{(h)})^s=\rho_i^{(h)}$ for every $0\le s\le1$. Therefore,
\begin{equation}
\xi_\pi^{0,1}(s)=-\log\!\left(\frac1N\sum_{i=1}^NF_{i,\pi(i)}\right),\qquad \xi_{\mathrm{acr}}=-\log F_\star.
\label{eq:pure-uniform-xi-acr}
\end{equation}

Using $P_{1,\Pi}\preceq\kappa^{-1}T_{1,\Pi}$ and Eq.~\eqref{eq:pure-uniform-branch-expansion}, we obtain
\begin{equation}
P_e^{(M)}\le\eta_0\kappa^{-1}N^{-M}\sum_{\Pi}\sum_{\alpha,\beta\in\mathcal A_\Pi}|\braket{\Phi_{\Pi,\alpha}^{(0)}}{\Phi_{\Pi,\beta}^{(1)}}|^2.
\label{eq:support-test-branch-bound}
\end{equation}
For fixed $\Pi$, $\alpha$, and $\beta$, the overlap factorizes as $|\braket{\Phi_{\Pi,\alpha}^{(0)}}{\Phi_{\Pi,\beta}^{(1)}}|^2=\prod_{B\in\Pi}F_{\alpha(B),\beta(B)}^{|B|}$. Equivalently, assigning $i_m=\alpha(B)$ and $j_m=\beta(B)$ for the unique block $B\in\Pi$ containing $m$ rewrites Eq.~\eqref{eq:support-test-branch-bound} as
\begin{equation}
P_e^{(M)}\le\eta_0\kappa^{-1}N^{-M}\sum_{\substack{\mathbf i,\mathbf j\in[N]^M\\\eqp(\mathbf i)=\eqp(\mathbf j)}}\prod_{m=1}^MF_{i_m,j_m}.
\label{eq:support-test-sequence-bound}
\end{equation}

Whenever $\eqp(\mathbf i)=\eqp(\mathbf j)$, the correspondence sending each label appearing in $\mathbf i$ to the label occupying the same positions in $\mathbf j$ is a bijection between the two used-label sets. It therefore extends to a permutation $\pi\in S_N$ satisfying $j_m=\pi(i_m)$ for every $m$. Summing over all $\pi\in S_N$ may count a pair $(\mathbf i,\mathbf j)$ more than once \footnote{For example, the indices permutated may not appear in all $M$ samples.}, but all summands are nonnegative. Thus
\begin{equation}
P_e^{(M)}\le\eta_0\kappa^{-1}N^{-M}\sum_{\pi\in S_N}\sum_{\mathbf i\in[N]^M}\prod_{m=1}^MF_{i_m,\pi(i_m)}.
\end{equation}
For each fixed permutation $\pi$, the inner sum factorizes:
\begin{equation}
N^{-M}\sum_{\mathbf i\in[N]^M}\prod_{m=1}^MF_{i_m,\pi(i_m)}=\left(\frac1N\sum_{i=1}^NF_{i,\pi(i)}\right)^M.
\end{equation}
Consequently,
\begin{equation}
P_e^{(M)}\le\eta_0\kappa^{-1}\sum_{\pi\in S_N}\left(\frac1N\sum_{i=1}^NF_{i,\pi(i)}\right)^M\le\eta_0\kappa^{-1}N!F_\star^M.
\label{eq:pure-uniform-achievability}
\end{equation}

If $F_\star>0$, Eq.~\eqref{eq:pure-uniform-achievability} implies
\begin{equation}
E=\lim_{M\to\infty}-\frac1M\log P_e^{(M)}\ge-\log F_\star=\xi_{\mathrm{acr}}.
\end{equation}
If $F_\star=0$, Eq.~\eqref{eq:pure-uniform-achievability} gives $P_{e,\mathrm{opt}}^{(M)}=0$ for every $M\ge1$, so the same conclusion holds with the convention $-\log0=+\infty$. Combining this achievability bound with the preceding converse $E\le\xi_{\mathrm{acr}}$ proves that
\begin{equation}
E=\xi_{\mathrm{acr}}.
\end{equation}

\paragraph{\textbf{Relation between the Chernoff exponent and the Wasserstein distance.}} Recall \(F_{ij}:=\Tr(\rho_i^{(0)}\rho_j^{(1)})\) and \(C_{ij}:=1-F_{ij}\). For two uniform ensembles of equal cardinality \(N\), define
\begin{equation}
\Gamma_N:=\left\{\gamma\in\mathbb R_+^{N\times N}:\sum_{j=1}^N\gamma_{ij}=\frac1N,\ \sum_{i=1}^N\gamma_{ij}=\frac1N\right\},
\label{eq:uniform-transport-plans}
\end{equation}
and the Wasserstein distance associated with the cost \(C_{ij}\) by
\begin{equation}
W(\calE_0,\calE_1):=\min_{\gamma\in\Gamma_N}\sum_{i,j=1}^N\gamma_{ij}C_{ij}.
\label{eq:uniform-wasserstein-distance}
\end{equation}

For every \(\gamma\in\Gamma_N\), the matrix \(N\gamma\) is doubly stochastic. By the Birkhoff--von Neumann theorem, there exist coefficients \(\lambda_\pi\ge0\), \(\pi\in S_N\), with \(\sum_{\pi\in S_N}\lambda_\pi=1\), such that
\[
\gamma_{ij}=\frac1N\sum_{\pi\in S_N}\lambda_\pi\delta_{j,\pi(i)}.
\]
Since the transport cost is linear in \(\gamma\),
\[
\sum_{i,j=1}^N\gamma_{ij}C_{ij}=\sum_{\pi\in S_N}\lambda_\pi\frac1N\sum_{i=1}^NC_{i,\pi(i)}\ge\min_{\pi\in S_N}\frac1N\sum_{i=1}^NC_{i,\pi(i)}.
\]
Conversely, for every \(\pi\in S_N\), the permutation plan \(\gamma_{ij}=N^{-1}\delta_{j,\pi(i)}\) belongs to \(\Gamma_N\). Therefore,
\begin{align}
W(\calE_0,\calE_1)&=\min_{\pi\in S_N}\frac1N\sum_{i=1}^NC_{i,\pi(i)}=\min_{\pi\in S_N}\frac1N\sum_{i=1}^N\left(1-F_{i,\pi(i)}\right)\notag\\
&=1-\max_{\pi\in S_N}\frac1N\sum_{i=1}^NF_{i,\pi(i)}=1-F_\star.
\label{eq:wasserstein-matching-fidelity}
\end{align}
Since the preceding result gives \(E=\xi_{\mathrm{acr}}=-\log F_\star\) for finite uniform pure-state ensembles, Eq.~\eqref{eq:wasserstein-matching-fidelity} yields
\begin{equation}
E=\xi_{\mathrm{acr}}=-\log\!\left[1-W(\calE_0,\calE_1)\right],
\label{eq:chernoff-wasserstein-relation}
\end{equation}
or equivalently \(W(\calE_0,\calE_1)=1-e^{-E}=1-e^{-\xi_{\mathrm{acr}}}\). This completes the proof.
\end{proof}

